<script setup>
import { ref,computed,watch,onMounted,onUnmounted,nextTick } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { marked } from 'marked';
import SearchBox from './SearchBox.vue';
import PostPreview from './PostPreview.vue';
import sanitizeHtml from 'sanitize-html';
const route=useRoute(),router=useRouter();
const data=ref(null),taxonomy=ref({categories:[],tags:[]}),user=ref(null),error=ref(''),loading=ref(true),comment=ref(''),reply=ref(null),progress=ref(0),focus=ref(false),csrf=ref(''),username=ref('reader'),password=ref('campus123'),activeHeading=ref(''),tocDialog=ref(null),feedTab=ref('latest'),community=ref({series:[]}),trends=ref([]);
const exploring=computed(()=>kind.value==='list');
const hasSearch=computed(()=>Object.keys(route.query).some(k=>['q','tagId','categoryId'].includes(k)));
async function searchTerm(q){router.push({path:'/articles',query:q?{q}:{}})}
const kind=computed(()=>route.path==='/'?'home':route.path==='/articles'?'list':route.path.startsWith('/articles/')?'article':route.path.startsWith('/users/')?'author':route.path==='/login'?'login':'favorites');
async function api(path,options={}){const r=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.method?{'X-CSRF-Token':csrf.value}:{}),...options.headers}});const result=await r.json();if(!r.ok)throw new Error(result.message||'请求失败');return result.data}
async function token(){csrf.value=(await api('/auth/csrf')).token}
async function load(){loading.value=true;error.value='';data.value=null;focus.value=false;try{if(kind.value==='home'){const [home,feed]=await Promise.all([api('/home'),api('/articles?page='+encodeURIComponent(route.query.page||'1'))]);data.value={...home,feed}}if(kind.value==='list'){data.value=await api('/articles?'+new URLSearchParams(route.query));trends.value=await api('/trends')}if(kind.value==='article'){const [article,comments]=await Promise.all([api('/articles/'+route.params.id),api('/articles/'+route.params.id+'/comments?page='+encodeURIComponent(route.query.commentPage||'1'))]);data.value={article,comments}}if(kind.value==='author'){const [profile,articles,series]=await Promise.all([api('/users/'+route.params.id+'/profile'),api('/articles?'+new URLSearchParams({authorId:route.params.id,page:route.query.page||'1'})),api('/users/'+route.params.id+'/series')]);data.value={profile,articles,series}}if(kind.value==='favorites')data.value=await api('/me/favorites?'+new URLSearchParams(route.query));}catch(e){error.value=e.message}finally{loading.value=false;await nextTick();updateProgress();if(route.hash){try{document.getElementById(decodeURIComponent(route.hash.slice(1)))?.scrollIntoView()}catch{}}}}
watch(()=>route.path+'?'+new URLSearchParams(route.query).toString(),load);
onMounted(async()=>{window.addEventListener('scroll',updateProgress,{passive:true});try{await token();user.value=await api('/auth/me');taxonomy.value=await api('/taxonomy');community.value=await api('/home');trends.value=await api('/trends')}catch(e){error.value=e.message}await load()});
onUnmounted(()=>window.removeEventListener('scroll',updateProgress));
function updateProgress(){const el=document.querySelector('.article-body');if(!el){progress.value=0;activeHeading.value='';return}const r=el.getBoundingClientRect();progress.value=Math.max(0,Math.min(100,Math.round((window.innerHeight-r.top)/Math.max(r.height,1)*100)));const headings=[...el.querySelectorAll('h2[id],h3[id]')];let current=headings[0];for(const h of headings){if(h.getBoundingClientRect().top<=120)current=h;else break}activeHeading.value=current?.id||''}
const rendered=computed(()=>{if(!data.value?.article)return {html:'',headings:[]};const headings=[],counts={};const renderer=new marked.Renderer();renderer.html=()=>'';renderer.heading=({tokens,depth})=>{const text=tokens.map(t=>t.text||'').join('');const key=text.toLowerCase().replace(/[^\p{L}\p{N}]+/gu,'-')||'section';counts[key]=(counts[key]||0)+1;const id=`h-${key}-${counts[key]}`;if(depth===2||depth===3)headings.push({id,text,depth});return `<h${depth} id="${id}">${marked.parser(tokens)}</h${depth}>`};const html=marked.parse(data.value.article.bodyMarkdown,{renderer});return {html:sanitizeHtml(html,{allowedTags:sanitizeHtml.defaults.allowedTags.concat(['img']),allowedAttributes:{...sanitizeHtml.defaults.allowedAttributes,h2:['id'],h3:['id'],img:['src','alt']},allowedSchemes:['http','https','mailto']}),headings}});
async function action(fn){error.value='';try{await fn()}catch(e){error.value=e.message}}
async function login(){await action(async()=>{await api('/dev/login',{method:'POST',body:JSON.stringify({username:username.value,password:password.value})});await token();user.value=await api('/auth/me');const next=String(route.query.next||'/');router.push(next.startsWith('/')&&!next.startsWith('//')?next:'/')})}
async function logout(){await action(async()=>{await api('/dev/logout',{method:'POST'});user.value=null;await token();router.push('/')})}
function requireUser(){if(!user.value){router.push({path:'/login',query:{next:route.fullPath}});return false}return true}
async function favorite(id,on){if(!requireUser())return;await action(async()=>{await api('/articles/'+id+'/favorite',{method:on?'PUT':'DELETE'});await load()})}
async function submit(){if(!requireUser())return;await action(async()=>{await api('/articles/'+route.params.id+'/comments',{method:'POST',body:JSON.stringify({content:comment.value,parentId:reply.value?.id})});comment.value='';const wasReply=!!reply.value;reply.value=null;if(!wasReply && Number(route.query.commentPage||1)!==1)await router.push({query:{...route.query,commentPage:'1'}});else await load();await nextTick();document.querySelector('#comments')?.scrollIntoView()})}
async function remove(id){await action(async()=>{await api('/comments/'+id,{method:'DELETE'});await load()})}
function changePage(p){router.push({query:{...route.query,page:String(p)}})}
function changeCommentPage(p){router.push({query:{...route.query,commentPage:String(p)},hash:'#comments'}).then(()=>nextTick(()=>document.querySelector('#comments')?.scrollIntoView()))}
function search(e){const fd=new FormData(e.target);router.push({path:'/articles',query:Object.fromEntries([...fd].filter(([,v])=>v))})}
</script>
<template>
  <div :class="{focused:focus, 'social-shell':true}">
    <div v-if="kind==='article'" class="progress" :style="{width:progress+'%'}" aria-hidden="true"></div>
    <aside class="social-sidebar" aria-label="主导航">
      <RouterLink to="/" class="social-brand"><span class="brand-mark">o<span>.</span></span><strong>OnlyCampus</strong></RouterLink>
      <nav class="social-nav">
        <RouterLink to="/" :class="{'nav-current':kind==='home'}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M3 10.5 12 3l9 7.5V20a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/></svg><span>首页</span></RouterLink>
        <RouterLink to="/articles" :class="{'nav-current':exploring}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/></svg><span>探索</span></RouterLink>
        <RouterLink :to="user?'/me/favorites':'/login?next=/me/favorites'"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M6 3.5h12v17L12 17l-6 3.5z" stroke-linejoin="round"/></svg><span>收藏</span></RouterLink>
        <RouterLink v-if="!user" to="/login"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="8" r="3.5"/><path d="M5 20c.5-4 3-6 7-6s6.5 2 7 6"/></svg><span>登录</span></RouterLink>
        <RouterLink v-else :to="'/users/'+user.id" class="nav-profile"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M10 4H5v16h5M14 8l4 4-4 4M8 12h10"/></svg><span>个人中心</span></RouterLink>
      </nav>
      <RouterLink :to="user?'/users/'+user.id:'/login'" class="social-account" aria-label="个人中心"><span class="avatar avatar-user">{{user?.nickname?.slice(0,1)||'我'}}</span><strong>{{user?.nickname||'个人中心'}}</strong></RouterLink>
    </aside>
    <main class="social-main center-column"><div v-if="error" class="notice" role="alert">{{error}} <button class="link-button" @click="load">重试</button></div><div v-if="loading" class="state">正在加载内容…</div>
    <template v-else-if="kind==='home' && data">
      <div class="home-content">
        <section class="feed" aria-label="校园文章">
          <header class="feed-header"><h1>首页</h1><RouterLink class="mobile-search-link" to="/articles" aria-label="搜索文章"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/></svg></RouterLink><div class="feed-tabs"><button :class="{selected:feedTab==='latest'}" @click="feedTab='latest'">最新</button><button :class="{selected:feedTab==='featured'}" @click="feedTab='featured'">精选</button></div></header>
          <div class="feed-context"><span class="context-dot"></span><span>校园里的新鲜事</span><RouterLink to="/articles">探索更多 <span aria-hidden="true">→</span></RouterLink></div>
          <div class="feed-posts">
            <PostPreview v-for="a in (feedTab==='latest'?data.feed.items:data.featured)" :key="a.id" :post="a"/>
            <p v-if="!(feedTab==='latest'?data.feed.items:data.featured).length" class="feed-empty">暂无文章</p>
          </div>
          <div v-if="feedTab==='latest' && (data.feed.page>1 || data.feed.page*data.feed.pageSize<Number(data.feed.total))" class="pagination"><button :disabled="data.feed.page<=1" @click="changePage(data.feed.page-1)">上一页</button><span>{{data.feed.page}}</span><button :disabled="data.feed.page*data.feed.pageSize>=Number(data.feed.total)" @click="changePage(data.feed.page+1)">下一页</button></div>
        </section>

      </div>
    </template>
    <template v-else-if="kind==='list' && data"><header class="explore-header"><SearchBox :value="String(route.query.q||'')" @search="searchTerm"/></header><section v-if="!hasSearch" class="trend-list"><h1>热搜榜</h1><RouterLink v-for="(t,index) in trends" :key="t.term" :to="{path:'/articles',query:{q:t.term}}" class="trend-row"><span>{{index+1}}</span><div><strong>{{t.term}}</strong><p>{{t.count}} 次搜索</p></div></RouterLink><p v-if="!trends.length" class="empty">还没有热门搜索</p></section><div v-if="hasSearch" class="search-results"><h1 class="visually-hidden">搜索结果</h1><nav class="feed-tabs search-tabs" aria-label="搜索结果排序"><button :class="{selected:route.query.sort!=='updated'}" @click="router.push({query:{...route.query,sort:'latest',page:'1'}})">最新</button><button :class="{selected:route.query.sort==='updated'}" @click="router.push({query:{...route.query,sort:'updated',page:'1'}})">最近更新</button></nav><div v-if="route.query.categoryId || route.query.tagId" class="active-search-filter"><span>{{taxonomy.categories.find(c=>c.id===route.query.categoryId)?.name || taxonomy.tags.find(t=>t.id===route.query.tagId)?.name || '筛选结果'}}</span><button @click="router.push({path:'/articles',query:route.query.q?{q:route.query.q}:{}})">清除筛选</button></div><PostPreview v-for="a in data.items" :key="a.id" :post="a"/><div v-if="!data.items.length" class="search-empty"><h2>没有找到相关帖子</h2><p>试试其他关键词。</p></div><nav v-if="data.page>1 || data.page*data.pageSize<Number(data.total)" class="pagination" aria-label="搜索结果分页"><button :disabled="data.page<=1" @click="changePage(data.page-1)">上一页</button><span>{{data.page}}</span><button :disabled="data.page*data.pageSize>=Number(data.total)" @click="changePage(data.page+1)">下一页</button></nav></div></template>
    <template v-else-if="kind==='article' && data"><div class="reading-toolbar"><RouterLink to="/articles">← 返回文章</RouterLink><button @click="focus=!focus">{{focus?'退出专注阅读':'专注阅读'}}</button></div><button v-if="rendered.headings.length" class="mobile-toc-toggle" aria-haspopup="dialog" @click="tocDialog.showModal()">打开文章目录</button><dialog ref="tocDialog" class="mobile-toc-dialog" aria-labelledby="mobile-toc-title" @click.self="tocDialog.close()"><div class="drawer-head"><strong id="mobile-toc-title">文章目录</strong><button @click="tocDialog.close()" aria-label="关闭文章目录">关闭</button></div><nav aria-label="文章目录"><a v-for="h in rendered.headings" :key="h.id" :href="'#'+h.id" :class="{indent:h.depth===3,active:activeHeading===h.id}" :aria-current="activeHeading===h.id?'location':undefined" @click="tocDialog.close()">{{h.text}}</a></nav></dialog><article class="article-layout"><div><header class="article-header"><p class="section-label">{{data.article.category}}</p><h1>{{data.article.title}}</h1><p class="article-summary">{{data.article.summary}}</p><RouterLink :to="'/users/'+data.article.authorId">{{data.article.author}}</RouterLink><span> · {{new Date(data.article.publishedAt).toLocaleDateString('zh-CN')}}</span><div class="tags"><span v-for="tag in data.article.tags" :key="tag">{{tag}}</span></div></header><div class="article-body" v-html="rendered.html"></div><div class="article-actions"><button @click="favorite(data.article.id,!data.article.favorited)">{{data.article.favorited?'取消收藏':'收藏文章'}}</button><span v-if="data.article.series">所属专栏：{{data.article.series.name}}</span></div><nav v-if="data.article.series && (data.article.series.previous || data.article.series.next)" class="chapter-nav" aria-label="专栏文章导航"><RouterLink v-if="data.article.series.previous" :to="'/articles/'+data.article.series.previous.id"><small>上一篇</small><strong>{{data.article.series.previous.title}}</strong></RouterLink><span v-else></span><RouterLink v-if="data.article.series.next" :to="'/articles/'+data.article.series.next.id"><small>下一篇</small><strong>{{data.article.series.next.title}}</strong></RouterLink></nav><section id="comments" class="comments"><h2>一起讨论</h2><form @submit.prevent="submit"><label for="comment">{{reply?'回复 '+reply.nickname:'写下你的想法'}}</label><textarea id="comment" v-model="comment" maxlength="500" rows="4" placeholder="分享你的想法…"></textarea><div><button class="primary">发表评论</button> <button v-if="reply" type="button" @click="reply=null">取消回复</button></div></form><div v-for="c in data.comments.items" :key="c.id" class="comment"><strong>{{c.nickname}}</strong><p>{{c.content||'该评论已不可见'}}</p><button v-if="c.status==='VISIBLE'" @click="reply=c">回复</button><button v-if="user && c.userId===user.id && c.status==='VISIBLE'" @click="remove(c.id)">删除</button><div v-for="r in c.replies" :key="r.id" class="reply"><strong>{{r.nickname}}</strong><p>{{r.content||'该评论已不可见'}}</p><button v-if="user && r.userId===user.id && r.status==='VISIBLE'" @click="remove(r.id)">删除</button></div></div><p v-if="!data.comments.items.length" class="empty">{{Number(data.comments.total) ? '此页没有评论，请返回上一页。' : '还没有评论，来分享第一个想法。'}}</p><nav v-if="Number(data.comments.total)>data.comments.pageSize || data.comments.page>1" class="pagination" aria-label="评论分页"><button :disabled="data.comments.page<=1" @click="changeCommentPage(data.comments.page-1)">上一页</button><span>第 {{data.comments.page}} 页</span><button :disabled="data.comments.page*data.comments.pageSize>=Number(data.comments.total)" @click="changeCommentPage(data.comments.page+1)">下一页</button></nav></section></div><aside class="toc"><strong>文章目录</strong><a v-for="h in rendered.headings" :key="h.id" :href="'#'+h.id" :class="{indent:h.depth===3,active:activeHeading===h.id}" :aria-current="activeHeading===h.id?'location':undefined">{{h.text}}</a><p v-if="!rendered.headings.length">这篇文章暂无目录。</p></aside></article></template>
    <template v-else-if="kind==='author' && data"><section class="page-intro"><h1>{{data.profile.nickname}}</h1><button v-if="user && String(user.id)===String(data.profile.id)" class="profile-logout" @click="logout">退出登录</button><p>{{data.profile.bio||'这个人还没有填写简介。'}}</p></section><section class="section"><h2>公开文章</h2><div class="profile-posts"><PostPreview v-for="a in data.articles.items" :key="a.id" :post="a"/><p v-if="!data.articles.items.length" class="empty">{{Number(data.articles.total) ? '此页没有文章，请返回上一页。' : '暂时没有公开文章。'}}</p></div><nav v-if="Number(data.articles.total)>data.articles.pageSize || data.articles.page>1" class="pagination" aria-label="作者文章分页"><button :disabled="data.articles.page<=1" @click="changePage(data.articles.page-1)">上一页</button><span>第 {{data.articles.page}} 页</span><button :disabled="data.articles.page*data.articles.pageSize>=Number(data.articles.total)" @click="changePage(data.articles.page+1)">下一页</button></nav></section><section class="section"><h2>成长专栏</h2><div v-for="s in data.series" :key="s.id" class="series-row"><strong>{{s.name}}</strong><p>{{s.description}}</p></div><p v-if="!data.series.length">暂时没有公开专栏。</p></section></template>
    <template v-else-if="kind==='favorites' && data"><section class="page-intro"><h1>我的收藏</h1></section><div v-for="a in data.items" :key="a.id" class="favorite-row"><div><RouterLink v-if="a.available" :to="'/articles/'+a.id"><h3>{{a.title}}</h3><p>{{a.summary}}</p></RouterLink><p v-else>文章已不可用</p></div><button @click="favorite(a.id,false)">取消收藏</button></div><p v-if="!data.items.length" class="empty">还没有收藏文章。</p><div class="pagination"><button :disabled="data.page<=1" @click="changePage(data.page-1)">上一页</button><span>第 {{data.page}} 页</span><button :disabled="data.page*data.pageSize>=data.total" @click="changePage(data.page+1)">下一页</button></div></template>
    <template v-else-if="kind==='login'"><section class="login"><h1>登录测试账号</h1><p>这是联调用的临时入口，正式登录由账号模块接入。</p><form @submit.prevent="login"><label>账号<input v-model="username" required></label><label>密码<input v-model="password" type="password" required></label><button class="primary">登录</button></form></section></template>
    </main><aside class="social-discover shared-discover" aria-label="探索内容"><SearchBox v-if="!exploring" @search="searchTerm"/><section class="discover-block"><h2>浏览分类</h2><RouterLink v-for="c in taxonomy.categories" :key="c.id" :to="{path:'/articles',query:{categoryId:c.id}}" class="discover-link"><span>{{c.name}}</span><span aria-hidden="true">→</span></RouterLink></section><section v-if="community.series.length" class="discover-block"><h2>成长专栏</h2><div v-for="s in community.series" :key="s.id" class="discover-series"><RouterLink :to="'/users/'+s.authorId">{{s.name}}</RouterLink><p>{{s.description}}</p></div></section></aside>
  </div>
</template>
